USE DATABASE SUPPLYCHAIN_DB;
CREATE TABLE IF NOT EXISTS RAW.ORDERS (ORDER_ID VARCHAR, CUSTOMER_ID VARCHAR, ORDER_DATE VARCHAR, STATUS VARCHAR, SOURCE_FILE VARCHAR, BATCH_ID VARCHAR, INGESTED_AT TIMESTAMP_NTZ);
CREATE TABLE IF NOT EXISTS RAW.ORDER_ITEMS (ORDER_ITEM_ID VARCHAR, ORDER_ID VARCHAR, PRODUCT_ID VARCHAR, QUANTITY VARCHAR, UNIT_PRICE VARCHAR, SOURCE_FILE VARCHAR, BATCH_ID VARCHAR, INGESTED_AT TIMESTAMP_NTZ);
CREATE TABLE IF NOT EXISTS RAW.PRODUCTS (PRODUCT_ID VARCHAR, PRODUCT_NAME VARCHAR, CATEGORY VARCHAR, UNIT_PRICE VARCHAR, SUPPLIER_ID VARCHAR, REORDER_LEVEL VARCHAR, SOURCE_FILE VARCHAR, BATCH_ID VARCHAR, INGESTED_AT TIMESTAMP_NTZ);
CREATE TABLE IF NOT EXISTS RAW.CUSTOMERS (CUSTOMER_ID VARCHAR, REGION VARCHAR, CUSTOMER_SEGMENT VARCHAR, SOURCE_FILE VARCHAR, BATCH_ID VARCHAR, INGESTED_AT TIMESTAMP_NTZ);
CREATE TABLE IF NOT EXISTS RAW.WAREHOUSES (WAREHOUSE_ID VARCHAR, WAREHOUSE_NAME VARCHAR, REGION VARCHAR, SOURCE_FILE VARCHAR, BATCH_ID VARCHAR, INGESTED_AT TIMESTAMP_NTZ);
CREATE TABLE IF NOT EXISTS RAW.INVENTORY (INVENTORY_ID VARCHAR, PRODUCT_ID VARCHAR, WAREHOUSE_ID VARCHAR, SNAPSHOT_DATE VARCHAR, QUANTITY_ON_HAND VARCHAR, UNIT_COST VARCHAR, SOURCE_FILE VARCHAR, BATCH_ID VARCHAR, INGESTED_AT TIMESTAMP_NTZ);
CREATE TABLE IF NOT EXISTS RAW.SUPPLIERS (SUPPLIER_ID VARCHAR, SUPPLIER_NAME VARCHAR, COUNTRY VARCHAR, LEAD_TIME_DAYS VARCHAR, SOURCE_FILE VARCHAR, BATCH_ID VARCHAR, INGESTED_AT TIMESTAMP_NTZ);
CREATE TABLE IF NOT EXISTS RAW.PURCHASE_ORDERS (PURCHASE_ORDER_ID VARCHAR, SUPPLIER_ID VARCHAR, PRODUCT_ID VARCHAR, ORDER_DATE VARCHAR, QUANTITY VARCHAR, RECEIVED_DATE VARCHAR, SOURCE_FILE VARCHAR, BATCH_ID VARCHAR, INGESTED_AT TIMESTAMP_NTZ);
CREATE TABLE IF NOT EXISTS RAW.SHIPMENTS (ORDER_ID VARCHAR, ORDER_DATE VARCHAR, SHIPMENT_ID VARCHAR, WAREHOUSE_ID VARCHAR, SHIP_DATE VARCHAR, PROMISED_DELIVERY_DATE VARCHAR, ACTUAL_DELIVERY_DATE VARCHAR, SOURCE_FILE VARCHAR, BATCH_ID VARCHAR, INGESTED_AT TIMESTAMP_NTZ);
